	// Create a certificate request with the existing key
	csr, err := x509util.CreateCertificateRequest(commonName, []string{}, existingKey)
	if err != nil {
		return nil, err
	}

	// Create a template for the root certificate
	template, err := x509util.NewCertificate(csr, x509util.WithTemplate(x509util.DefaultRootTemplate, x509util.CreateTemplateData(commonName, []string{})))
	if err != nil {
		return nil, err
	}

	cert := template.GetCertificate()
	cert.NotBefore = time.Now().Truncate(time.Second)
	cert.NotAfter = cert.NotBefore.Add(defaultRootLifetime)

	// Create the certificate using the existing key
	root, err := x509util.CreateCertificate(cert, cert, existingKey.Public(), existingKey)
	if err != nil {
		return nil, err
	}

	return root, nil
}
EOF
```

